INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (15, 'Summer 2027 Intern - Software Engineer', 'Salesforce, Inc.', 'Class of 2028 Intern - Software Engineer AMTS Location: Hyderabad/Bangalore, India This is your time to shine and be part of Salesforce, a world leader in enterprise cloud computing. We deliver innovations to our customers through the year including 3 major releases in a year. Our innovation is powered through our customer 360 Platform that enables us to bring value to all parts of the customer’s organizations.. As a software engineering intern you will get to contribute right away as a member of one of our Scrum teams to one or more software engineering aspects into the future releases. You will get to be part of the one or more aspects of the engineering lifecycle of tools and/ or features that enable our solutions to reach millions of end users and enterprises who use our important applications and services every day to run their business. We also look to you to help deliver high quality software through automated testing, and own your service in production with real-time monitoring', 'JavaScript, React, Node.js, Python', 'Hyderabad', '3-6 Months', '2026-04-26 11:25:47', '2026-04-26 11:25:47');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (16, 'Software Developer Intern (problem Solving & Full-stack Focus)', 'Creyente Infotech', 'Internship Details: Role: Software Developer Intern Mode: On-site (Hyderabad) Duration: 6 months (Full time based on performance) Start Date: Immediate Stipend: As per company standards About the Role: We are looking for a highly motivated Software Developer Intern with strong problem-solving and Data Structures & Algorithms (DSA) skills.\n\nThis role is ideal for candidates who enjoy tackling complex challenges, writing efficient code, and building scalable applications. You will work on designing and developing core modules, implementing infrastructure workflows using Terraform, and contributing to modern frontend applications using React.\n\nThe role emphasizes logical thinking, algorithmic efficiency, and clean coding practices.\n\nKey Responsibilities: Solve complex programming problems using efficient algorithms and data structures Design and implement scalable backend components using Java and Go Develop responsive and interactive user interfaces using React Write clean, maintainable,', 'JavaScript, React, Node.js, Python', 'Bunghmun', '3-6 Months', '2026-04-26 11:25:47', '2026-04-26 11:25:47');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (17, 'Software Engineering Intern — Cross-Platform Mobile and Backend', 'VIAN', '₹20,000/month inr · Claude Code + Cursor Pro paid · Remote · Full-time · 6 months · Founding Engineer offer for the one who earns it\n\nAbout the founder\n\nVignesh Bageerathan. Previously Product Manager at Illumina (genomics products shipped to clinical labs globally), Bioinformatics Analyst at the University of Arizona Cancer Center. Masters from Northeastern University. MIT certificates in AI in Drug Discovery and Business Applications of AI.\n\nBuilding a mobile-first consumer AI product for a high-bar professional audience. Ships globally in 12 weeks.\n\nThe role\n\nOne intern to own mobile and backend end to end. Under NDA on specifics, shared after a first call.\n\nYou will work daily on:\n\n• Cross-platform mobile app in Flutter (Dart, Riverpod) or React Native (TypeScript), shipping to iOS and Android, sub-0.1% crash rate target\n• 200+ domain-specific interactive tools generated from a JSON schema you design, each with offline support, input validation, source citations, and history\n• Supa', 'JavaScript, React, Node.js, Python', 'Chhatrapati Sambhajinagar', '3-6 Months', '2026-04-26 11:25:47', '2026-04-26 11:25:47');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (18, 'Software Engineering Intern, Summer 2026', 'Google', 'Join us for a 12+ week paid internship that offers personal and professional development, an executive speaker series, and community-building.\n\nThe Software Engineering\n\nInternship program will give you an opportunity to work on complex computer science solutions, develop scalable, distributed software systems, and also collaborate on multitudes of smaller projects that have universal appeal.\n\nInternship timeline May-Aug 2026.\n\nNote: By applying to this position you will have an opportunity to share your preferred working location from the following: Bengaluru, Karnataka, India; Hyderabad, Telangana, India; Pune, Maharashtra, India.Minimum qualifications:\n\n• Currently pursuing a Master\'s degree in research programs with a focus in software development, research, or other technical related fields.\n\n• Experience with one or more general purpose programming languages (e.g., Java, C/C++, Python, JavaScript, Go, etc.).\n\n• Experience in one or more of the following: architecting or developin', 'JavaScript, React, Node.js, Python', 'India', '3-6 Months', '2026-04-26 11:25:47', '2026-04-26 11:25:47');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (19, 'Hardware and Software Engineering Intern', 'Intel Technology India Pvt Ltd', 'Attraction Req : Intern Job Details: Job Description: Hardware Intern We have roles in Architecture, AI/ML, Digital and Analog domain. Hardware Engineer conducts research, definition, design, verification and documentation for SoC (System on a Chip) development. Performs logic design for integration of cell libraries, functional units, and sub-systems into SoC full chip designs. Register Transfer Level coding and simulation for SoCs. Contributes to the development of multidimensional designs involving the layout of complex integrated circuits. Will be working on aspects of the SoC design flow from high-level design to synthesis, place and route, timing, and power to create a design database that is ready for manufacturing. Initiates, guides, and coordinates overall design and development of new ideas and products. He/She should be willing to ramp up quickly on required areas like RTL, Verification/Validation, Structural Design/Physical Design, Analog, Firmware, Embedded etc. Software I', 'JavaScript, React, Node.js, Python', 'Bengaluru', '3-6 Months', '2026-04-26 11:25:47', '2026-04-26 11:25:47');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (20, 'Software Engineer, Intern at Stripe', 'Stripe', 'Stripe is hiring with Peerlist for a Internship Software Engineer, Intern. Required skills: Java,Ruby,JavaScript,Scala,Go', 'JavaScript, React, Node.js, Python', 'Bengaluru', '3-6 Months', '2026-04-26 11:25:47', '2026-04-26 11:25:47');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (21, 'Software Engineering Intern | OneSpotAI | Remote', 'OneSpotAI', 'OneSpotAI is an early-stage AI startup building modern AI-powered products and systems. We\'re looking for a proactive Software Engineering Intern who enjoys building products, solving real problems, and working in a fast-paced startup environment.\n\nWhat You\'ll Work On\n\n• Build and improve features across frontend and backend systems\n\n• Develop scalable APIs, dashboards, and internal tools\n\n• Collaborate with the team to ship product updates quickly\n\n• Work with databases, integrations, and cloud-based services\n\n• Debug issues, optimize performance, and improve reliability\n\n• Contribute to AI-powered product workflows and applications\n\nWhat We\'re Looking For\n\n• Strong fundamentals in software development and problem-solving\n\n• Familiarity with JavaScript/TypeScript or Python\n\n• Understanding of frontend or backend development concepts\n\n• Ability to learn quickly and work independently\n\n• Interest in startups, AI products, and modern software systems\n\nPerks\n\n• Competitive stipend\n\n• Full', 'JavaScript, React, Node.js, Python', 'Remote', '3-6 Months', '2026-05-25 15:26:48', '2026-05-25 15:26:48');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (22, 'Intern - Software Engineer', 'Mr. Cooper', 'At Mr. Cooper Group, You Make the Dream Possible.\n\nOur purpose is simple: Keeping the dream of homeownership alive. As a Mr. Cooper Group team member, you play a big role in making that dream possible. Around here, we know our roles and work together, volunteer to make a difference, and challenge the status quo when needed. Everything we do is in the care and service of our teammates and our customers.\n\nJoin us and make the dream of home ownership possible!\n\nWe are looking for high energy, passionate programmers who have a passion working in a full stack programming mode. Technology solves business problems. Our developers are adept at adopting to any technology that is right to solve that problem. They are trained to be Polyglot developers and they wear many hats and work across Web/Mobile/Analytics and Data Engineering\n\nMr. Cooper Group is an Equal Opportunity Employer. All qualified applicants will receive consideration for employment without regard to race, color, religion, sex, se', 'JavaScript, React, Node.js, Python', 'Chennai', '3-6 Months', '2026-05-25 15:26:48', '2026-05-25 15:26:48');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (23, 'Software Engineer (AI) Intern', 'Astro247 AI', 'Company Description\n\nAstro247 is a cutting-edge astrology platform that combines traditional astrological expertise with modern technology to deliver personalized, accurate, and accessible insights. Designed to guide users on aspects such as love, career, health, and personal growth, the platform integrates AI-powered tools and real expert astrologers for tailored experiences. With features like instant predictions, live consultations, and customized horoscopes based on unique birth charts, Astro247 is redefining how people interact with astrology. Our mission is to empower users to navigate life’s uncertainties with confidence and clarity.\n\nRole Description\n\nThis is a full-time, on-site Software Engineer (AI) Intern role located in Bengaluru. The intern will assist in designing, developing, and maintaining AI-driven software solutions tailored for astrological insights. Responsibilities include working on back-end development, implementing Object-Oriented Programming (OOP) principles,', 'JavaScript, React, Node.js, Python', 'Bengaluru', '3-6 Months', '2026-05-25 15:26:48', '2026-05-25 15:26:48');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (24, 'Software Developer Intern (React Native / Full Stack)', 'Ilume Labs', 'Seeking passionate 202526 graduates for a Software Developer Intern role to work on React Native, Node.js, MongoDB ,AWS , API, and scalable cloud solutions while gaining hands-on exposure to full-stack and AI-integrated product development.', 'JavaScript, React, Node.js, Python', 'Pune', '3-6 Months', '2026-05-25 15:26:48', '2026-05-25 15:26:48');
