INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (26, 'Software Engineer Intern - (Backend)', 'ScaleWave Technologies Pvt Ltd', '• This is an unpaid internship\n\nCompany Description\nScaleWave Technologies Pvt Ltd is an India-based technology company that specialises in building modern digital products, scalable backend platforms, and cloud-first software systems. Known for its flagship product LaaoDo, a hyperlocal platform for local commerce and fulfilment experiences, ScaleWave also delivers software engineering and technology services across web, mobile, backend, and cloud domains. The company emphasises practical innovation, robust architecture, and long-term trust to deliver reliable solutions.\nAt ScaleWave, the emphasis is on building modern systems and smarter scalability to advance digital transformation.\n\nRole Description\n\nThis is a full-time on-site role for a Software Engineer Intern (Backend) located in Delhi, India. The intern will be responsible for developing and maintaining backend software systems, writing efficient and reliable code, and collaborating with cross-functional teams. This role involv', 'JavaScript, React, Node.js, Python', 'New Delhi', '3-6 Months', '2026-05-25 15:26:48', '2026-05-25 15:26:48');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (27, 'Software Engineering Intern', 'Irastrive Technologies Private Limited', 'Job Information\n\n• Date Opened 03/26/2026\n• Job Type Full time\n• Industry Technology\n• City Saidapet\n• State/Province Tamil Nadu\n• Country India\n• Zip/Postal Code 600096\n\nJob Description\n\nWe are looking for a proactive, enthusiastic, and eager-to-learn Intern to join our team. This internship is a great opportunity for students or fresh graduates who want hands-on exposure to real-time projects, professional work culture, and practical industry experience.\n\nThe intern will work closely with the team on day-to-day activities, support ongoing projects, and gain knowledge in business processes, communication, coordination, and execution.\n\nKey Responsibilities\n\n• Support the team in daily operational and project-related activities\n• Assist in research, documentation, reporting, and follow-ups\n• Coordinate with internal teams for assigned tasks\n• Help in preparing presentations, spreadsheets, and other required documents\n• Participate in meetings and maintain notes/action items where requir', 'JavaScript, React, Node.js, Python', 'Vellore', '3-6 Months', '2026-05-25 15:26:48', '2026-05-25 15:26:48');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (28, 'Software Engineering Intern', 'VivahGo', 'As a Software Engineering Intern at Vivahgo, you will play a crucial role in contributing to a sophisticated polyglot microservices architecture that powers our core marketplace. Your responsibilities will include:\n\n- Microservices Development: Contributing to a polyglot repository using Go for high-performance backends, Python for data-heavy logic, and Java for enterprise-scale services.\n- API Design & Integration: Implementing and maintaining inter-service communication using gRPC and Protocol Buffers (protobuf), while ensuring robust external-facing REST/HTTP interfaces.\n- Container Orchestration: Managing service lifecycles using Kubernetes (K8s) and Docker, utilizing Skaffold to streamline local development and rapid deployment loops.\n- Infrastructure as Code: Assisting in provisioning and managing cloud resources through Terraform to ensure scalable and reproducible environments.\n- Data Management: Implementing distributed caching solutions with Redis and maintaining persistent d', 'JavaScript, React, Node.js, Python', 'New Delhi', '3-6 Months', '2026-05-25 15:26:48', '2026-05-25 15:26:48');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (29, 'Software Engineering - Internship (Paid)', 'SwiftB2B', 'SwiftB2B is an AI operating system for global supply chains that delivers live, item-level visibility and autonomous orchestration. The platform serves 3PLs, freight forwarders, brands, retailers, and manufacturers, helping them monitor every item, shipment, and exception in real time. SwiftB2B enables users to act automatically across the entire supply chain, from first mile to final decision, improving efficiency and responsiveness. As a technology-focused organization, SwiftB2B offers opportunities to work with advanced AI, data, and automation solutions that drive modern supply chain innovation.\n\nThis is a paid, full-time remote engineering internship with six months on the product engineering team, shipping features. Our stack is Angular on the front, .NET on the back, PostgreSQL or SQL Server underneath, Kafka between services. You will use Claude Code daily, which means the typing is fast and the thinking is the job: is this the right design, did the agent get the edge case wron', 'JavaScript, React, Node.js, Python', 'Remote', '3-6 Months', '2026-11-16 17:07:13', '2026-11-16 17:07:13');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (30, 'Software Engineer Intern', 'PayPal', 'The Company\nPayPal has been revolutionizing commerce globally for more than 25 years. Creating innovative experiences that make moving money, selling, and shopping simple, personalized, and secure, PayPal empowers consumers and businesses in approximately 200 markets to join and thrive in the global economy.\n\nWe operate a global, two-sided network at scale that connects hundreds of millions of merchants and consumers. We help merchants and consumers connect, transact, and complete payments, whether they are online or in person. PayPal is more than a connection to third-party payment networks. We provide proprietary payment solutions accepted by merchants that enable the completion of payments on our platform on behalf of our customers.\n\nWe offer our customers the flexibility to use their accounts to purchase and receive payments for goods and services, as well as the ability to transfer and withdraw funds. We enable consumers to exchange funds more safely with merchants using a variety', 'JavaScript, React, Node.js, Python', 'Chennai', '3-6 Months', '2026-11-16 17:07:13', '2026-11-16 17:07:13');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (31, 'Software Engineer, Intern | Bangalore, IN', 'Stripe', 'Software Engineer, Intern\r\n\r\n\r\n\r\nWho we are \r\n\r\n\r\nAbout Stripe \r\n\r\n\r\n\r\nStripe is a technology company focused on improving the conditions for economic growth and prosperity. We build programmable financial infrastructure, rethinking from first principles how financial services should work, to make it easier and cheaper for any business to start and scale. More than 10 million businesses build on Stripe, spanning the economic frontier-from solo founders to established enterprises-united by a practical focus on growth. The most ambitious companies in the world use Stripe as core infrastructure to grow faster. They process trillions of dollars a year on Stripe, equivalent to around 1.6% of global GDP. While economic growth makes everyone better off, open markets also enable greater variety. When any business can easily serve a global customer base, the quality and diversity of products in the world increase, and craft and creativity are unleashed into the smallest niches. Our own growth i', 'JavaScript, React, Node.js, Python', 'Bengaluru', '3-6 Months', '2026-11-16 17:07:13', '2026-11-16 17:07:13');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (32, 'Embedded Software Intern', 'Thales', 'Location: Bangalore, India\n\nThales is a global technology leader trusted by governments, institutions, and enterprises to tackle their most demanding challenges. From quantum applications and artificial intelligence to cybersecurity and 6G innovation, our solutions empower critical decisions rooted in human intelligence. Operating at the forefront of aerospace and space, cybersecurity and digital identity, we’re driven by a mission to build a future we can all trust.\n\nPresent in India since 1953, Thales is headquartered in Noida and has other operational offices and sites spread across Delhi, Gurugram, Bengaluru and Mumbai, among others. Over 2200 employees are working with Thales and its joint ventures in India. Since the beginning, Thales has been playing an essential role in India’s growth story by sharing its technologies and expertise in Defence, Aerospace and Cyber & Digital sectors. Thales has two engineering competence centres in India - one in Noida focused on Cyber & Digital ', 'JavaScript, React, Node.js, Python', 'Bengaluru', '3-6 Months', '2026-11-16 17:07:13', '2026-11-16 17:07:13');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (33, 'IT Intern - Software Development, Python & AI/ML', 'AI SAMRAT', 'Role Overview\nJoin AI SAMRAT as an IT Intern in Software Development, focusing on Python and AI/ML, located in Whitefield, Bengaluru, Karnataka. This 6–8 month Internship & Corporate Training Programme is designed for passionate students and fresh graduates seeking practical exposure to the IT industry.\n\nKey Responsibilities\n- Learn and apply programming skills in Python, Java, and programming fundamentals.\n- Engage in web development using HTML, CSS, JavaScript, and Full Stack Development.\n- Gain experience in data analytics, SQL, data visualization, and reporting.\n- Understand emerging technologies including Data Science, Machine Learning, and AI fundamentals.\n- Participate in live project execution, enhancing problem-solving, teamwork, communication, and corporate professionalism skills.\n\nRequired Qualifications\n- Passion for learning and innovation in the IT field.\n- Basic knowledge of programming languages such as Python and Java.\n- Familiarity with web development technologies in', 'JavaScript, React, Node.js, Python', 'India', '3-6 Months', '2026-11-16 17:07:13', '2026-11-16 17:07:13');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (34, 'Software Engineer Intern', 'DigiPlus IT', 'Location: Borivali, Mumbai\nAre currently pursuing or have completed a B.E./B.Tech degree.\n\nResponsibilities\n\nSoftware Development (75%)\n\n* Develop, test, and maintain modern web applications using Node.js, TypeScript, and React.js.\n* Build scalable and responsive frontend interfaces along with robust backend services.\n* Design, develop, and integrate RESTful APIs to support application functionality.\n* Troubleshoot, debug, and optimize applications to ensure high performance and reliability.\n* Write clean, maintainable, and efficient code following industry best practices and coding standards.\n* Work with databases, data models, and application architecture to support business requirements.\n* Participate in the complete software development lifecycle, from requirement analysis and planning to deployment and maintenance.\n* Collaborate with senior engineers on system design, code reviews, and technical discussions.\n* Contribute to testing, documentation, and continuous improvement initia', 'JavaScript, React, Node.js, Python', 'India', '3-6 Months', '2026-11-16 17:07:13', '2026-11-16 17:07:13');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (35, 'Software Engineer Intern', 'CredHive', 'Position Overview\n\nWe are a seed-funded startup focused on using state-of-the-art AI technologies to revolutionize the credit industry. Our team consists of experts in machine learning and software engineers who have worked at top-tier US tech companies like Apple, Amazon, etc , and we are passionate about using AI to improve access to credit information for businesses. We have the product on the market, the first clients, and sufficient runway. We are seeking an enthusiastic Software Engineer Intern. This internship is ideal for final year or graduate students (freshers may apply too) who are passionate about software development and are looking to gain real-world experience in a fast-paced startup environment. You\'ll work closely with our engineering team to develop and optimize our data processing tools, web scraping scripts, and contribute to various projects utilizing Python.\n\nKey Responsibilities\n• Python Development: Assist in the development and maintenance of Python applicatio', 'JavaScript, React, Node.js, Python', 'New Delhi', '3-6 Months', '2026-11-16 17:07:13', '2026-11-16 17:07:13');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (36, 'Software Engineering Intern (6 Months)', 'Enterprise AI', 'About the RoleWere hiring engineering interns who can think clearly, solve hard problems, and build real systems. Youll work across backend engineering, AI pipelines, vector search, and integrations contributing to production features from day one.\n\nWhat Youll DoBuild backend services in Java, Node.js, or Python\n\nDesign schemas and work with SQL databases (PostgreSQL)\n\nImplement integrations with external SaaS systems (REST APIs, webhooks)\n\nWork with embeddings, transformer-based models, and vector databases\n\nBuild and debug data processing pipelines end-to-end\n\nContribute to technical discussions, code reviews, and architecture decisions\n\nWhat You NeedProficiency in one of: Java, Node.js, or Python\n\nStrong foundation in data structures, algorithms, and core CS concepts\n\nUnderstanding of SQL and basic schema design\n\nClear reasoning and problem-solving ability\n\nAbility to learn new technologies quickly and operate with ownership\n\nNice to HaveExposure to transformer models or embedding w', 'JavaScript, React, Node.js, Python', 'India', '3-6 Months', '2026-11-16 17:07:13', '2026-11-16 17:07:13');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (37, 'Software Engineering Intern, ITC', 'NIKE', 'Become a Part of the NIKE, Inc. TeamNIKE, Inc. does more than outfit the worlds best athletes. It is a place to explore potential, obliterate boundaries and push out the edges of what can be. The company looks for people who can grow, think, dream and create. Its culture thrives by embracing diversity and rewarding imagination. The brand seeks achievers, leaders and visionaries. At NIKE, Inc. its about each person bringing skills and passion to a challenging and constantly evolving game.Who We Are Looking ForWere looking for graduates who are passionate about automation, business process simplification by learning and working on Industry leading platforms and tools such as ServiceNow, that help drive efficiency in business processes and services within organizations and across organizations. We are looking for passionate minds who would like to ride the wave of digital disruption with the ServiceNow platform at Nike. We are looking for candidates who would like to build digital platfor', 'JavaScript, React, Node.js, Python', 'India', '3-6 Months', '2026-11-16 17:07:13', '2026-11-16 17:07:13');
INSERT INTO `internships` (`id`, `title`, `company`, `description`, `skills`, `location`, `duration`, `createdAt`, `updatedAt`) VALUES (38, 'Software Development Intern', 'Park Place Technologies', 'Overview\n\nThe Engineering Team at Park Place Technologies, India is hiring a Software Engineering Intern – Backend to help build and ship innovative products using the most modern tech stack to solve real world problems at scale.\n\nThis internship is designed for early in career engineers and experienced interns who already have hands-on backend development experience and are eager to grow by working on real, production-grade systems. You will contribute directly to building services that support business-critical workflows, while learning how scalable systems are designed, built, tested, and operated by experienced engineering teams.\n\nWe are looking for curious, self-motivated individuals who are excited to learn, take ownership, and continuously improve. You will be joining a team that values engineering excellence, collaboration, and a culture built on openness, trust and diversity where questions are encouraged, and mentorship is part of the job.\n\nIf you are excited about starting y', 'JavaScript, React, Node.js, Python', 'Hyderabad', '3-6 Months', '2026-11-16 17:07:14', '2026-11-16 17:07:14');

DROP TABLE IF EXISTS `skills`;
CREATE TABLE `skills` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `role` enum('student','recruiter','admin') DEFAULT 'student',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `email_2` (`email`),
  UNIQUE KEY `email_3` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

